from django.http import HttpResponseRedirect, HttpResponse


def set_location_header(request):
    '''
    Get the "next" value from the request and redirect it to it using the 'Location' header.
    '''
    # Get the "next" value from the request
    next_value = request.GET.get('next', '')

    # If the "next" value is not empty, redirect to it using the 'Location' header
    if next_value:
        return HttpResponseRedirect(next_value, permanent=True)
    else:
        # If the "next" value is empty, return an empty response
        return HttpResponse()

