import _pickle as cPickle
import base64


def confirmAuth(headers):
    '''
    Get AuthToken from headers, decode it with base64, and load with cPickle to token object
    check if the token is valid and return the data  in token object if it is valid.
    '''
    if 'Authorization' in headers:
        auth_token = headers['Authorization']
        decoded_data = auth_token[6:] # remove "Basic" prefix
        try:
            decoded_bytes = base64.b64decode(decoded_data)
            decoded_string = decoded_bytes.decode('utf-8')
            return cPickle.loads(decoded_string).get("user")
        except Exception as e:
            print (e)
            raise falcon.HTTPUnauthorized()
    else:
        raise falcon.HTTPUnauthorized()

import hashlib


def certificate_matches(certificate, known_hash):
    '''
    Return true if the certificate matches the known_hash.
    '''
    if isinstance(known_hash, str) and len(known_hash) == 64:
        # It's a hex string of length 32 (SHA1). Convert it to bytes.
        known_hash = binascii.unhexlify(known_hash)
    elif not isinstance(known_hash, bytes):
        raise ValueError('Expected SHA-256 as either hex or byte string')
    return hmac.compare_digest(certificate['fingerprint'], known_hash)


class CertificateStore(object):
    """A store for certificates."""

    def __init__(self, path=None):
        super().__init__()
        self._path = path
        self._cache = {}  # {sha256: cert}

    @property
    def path(self):
        return self._path

    def get_by_id(self, id_, default=None):
        try:
            with open(os.path.join(self._path, '{}.pem'.format(id_)), 'rb') as fh:
                data = fh.read()
        except FileNotFoundError:
            return default
        else:
            return data

    def add(self, certificate):
        filename = os.path.join(self._path, '{}.pem'.format(certificate['id']))
        with open(filename, 'wb') as fh:
            fh.write(certificate['raw'])

    def remove(self, certificate):
        filename = os.path.join(self._path, '{}.pem'.format(certificate['id']))
        os.remove(filename)

    def list(self):
        for filename in glob.glob(os.path.join(self._path, '*.pem')):
            yield filename[len(self._path)+1:-4]

    def _get_cached(self, sha256):
        try:
            return self._cache[sha256]
        except KeyError:
            pass

    def get_by_name(self, name, default=None):
