def UDPMessaging(udp_ip, udp_port):
    '''
    Create a UDP socket that listens on the IP and port provided for DNS requests.
    Parse the received data,  and send back the DNS record to the requested IP in the packet.
    '''
    # Create a UDP socket
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)

    while True:
        print("Waiting for request...")
        data, addr = sock.recvfrom(1024) # buffer size is 1024 bytes

        if not data:
            continue

        try:
            parsedData = parseUDPpacket(data)
        except Exception as e:
            print('Error parsing data', str(e))
            continue

        responseRecord = None
        for rrType in parsedData['rrTypes']:
            resolvedDomain = resolvedDomainFromRRtype(rrType)
            if resolvedDomain != '':
                responseRecord = getARecordForHost(resolvedDomain)
                break

        if responseRecord == None:
            print('No valid RR type found')
            continue

        sendResponse(addr[0], responseRecord)

